1	// Test helpers: start server.mjs as a child process and talk HTTP to it.
2	import assert from 'node:assert/strict';
3	import { spawn } from 'node:child_process';
4	import { mkdtemp, rm, stat, writeFile } from 'node:fs/promises';
5	import { request as httpRequest } from 'node:http';
6	import { connect, createServer as createNetServer } from 'node:net';
7	import { tmpdir } from 'node:os';
8	import { dirname, join } from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = join(ROOT, 'server.mjs');
13	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
14	export const JSON_TYPE = 'application/json; charset=utf-8';
15	export const JSON_HEADERS = Object.freeze({ 'Content-Type': 'application/json' });
16	const EXIT_TIMEOUT_MS = 5000;
17	const LISTEN_TIMEOUT_MS = 10000;
18	const REQUEST_TIMEOUT_MS = 15000;
19	
20	/** Every error message the spec names, exactly. */
21	export const MSG = Object.freeze({
22	  internal: 'internal error',
23	  notFound: 'not found',
24	  method: 'method not allowed',
25	  bookingNotFound: 'booking not found',
26	  contentType: 'content type must be application/json',
27	  tooLarge: 'body too large',
28	  notObject: 'body must be a JSON object',
29	  room: 'room must be one of Aurora, Borealis, Cosmos',
30	  title: 'title must be 1 to 80 characters',
31	  date: 'date must be a valid YYYY-MM-DD date',
32	  start: 'start must be HH:MM',
33	  end: 'end must be HH:MM',
34	  order: 'end must be after start',
35	});
36	
37	/** Asserts an error reply: exact status, body exactly {error}, exact JSON content type. */
38	export function expectError(res, status, error) {
39	  assert.strictEqual(res.status, status, res.text);
40	  assert.deepStrictEqual(res.json, { error });
41	  assert.strictEqual(res.headers['content-type'], JSON_TYPE);
42	}
43	
44	let dateCounter = 0;
45	/** A date no earlier call returned (2040-01-02 onwards), so accepted bookings never overlap. */
46	export function uniqueDate() {
47	  dateCounter += 1;
48	  const month = String(1 + Math.floor(dateCounter / 28)).padStart(2, '0');
49	  const day = String(1 + (dateCounter % 28)).padStart(2, '0');
50	  return `2040-${month}-${day}`;
51	}
52	
53	/** Resolves true/false for an existing/missing path; rethrows any error other than ENOENT. */
54	export async function exists(path) {
55	  try {
56	    await stat(path);
57	    return true;
58	  } catch (err) {
59	    if (err.code === 'ENOENT') return false;
60	    throw err;
61	  }
62	}
63	
64	/** Runs fn(dir) with a fresh tmp dir that is always removed. */
65	export async function withTmpDir(fn) {
66	  const dir = await makeTmpDir();
67	  try {
68	    return await fn(dir);
69	  } finally {
70	    await rm(dir, { recursive: true, force: true });
71	  }
72	}
73	
74	/** Starts a server (see startServer), runs fn(server), always stops it. */
75	export async function withServer(opts, fn) {
76	  const server = await startServer(opts);
77	  try {
78	    return await fn(server);
79	  } finally {
80	    await server.stop();
81	  }
82	}
83	
84	/** A valid booking body; override any field. */
85	export const booking = (overrides = {}) => ({
86	  room: 'Aurora',
87	  title: 'Standup',
88	  date: '2026-11-03',
89	  start: '09:00',
90	  end: '10:00',
91	  ...overrides,
92	});
93	
94	export const makeTmpDir = () => mkdtemp(join(tmpdir(), 'rooms-test-'));
95	
96	/** Writes a data file in the server's layout. */
97	export const writeStore = (path, bookings = [], nextId = bookings.length + 1) =>
98	  writeFile(path, JSON.stringify({ nextId, bookings }));
99	
100	/** Environment without the caller's PORT / DATA_FILE; `undefined` values mean unset. */
101	function buildEnv(env) {
102	  const base = { ...process.env };
103	  delete base.PORT;
104	  delete base.DATA_FILE;
105	  const merged = { ...base, ...env };
106	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
107	}
108	
109	/** Spawns the server. Returns a handle with live stdout/stderr text and an exit promise. */
110	export function spawnServer({ cwd, env = {}, script = SERVER }) {
111	  const child = spawn(process.execPath, [script], { cwd, env: buildEnv(env) });
112	  const out = { stdout: '', stderr: '' };
113	  child.stdout.setEncoding('utf8').on('data', (d) => (out.stdout += d));
114	  child.stderr.setEncoding('utf8').on('data', (d) => (out.stderr += d));
115	  const exited = new Promise((resolve) => {
116	    child.on('close', (code, signal) => resolve({ code, signal }));
117	  });
118	  return {
119	    child,
120	    exited,
121	    stdout: () => out.stdout,
122	    stderr: () => out.stderr,
123	  };
124	}
125	
126	/** Runs the server until it exits by itself; fails if it is still running after the timeout. */
127	export async function runToExit(opts, timeoutMs = EXIT_TIMEOUT_MS) {
128	  const handle = spawnServer(opts);
129	  let timer;
130	  const timeout = new Promise((resolve) => {
131	    timer = setTimeout(() => resolve('timeout'), timeoutMs);
132	  });
133	  const result = await Promise.race([handle.exited, timeout]);
134	  clearTimeout(timer);
135	  if (result === 'timeout') {
136	    handle.child.kill('SIGKILL');
137	    await handle.exited;
138	    throw new Error(`server did not exit; stdout=${JSON.stringify(handle.stdout())}`);
139	  }
140	  return { code: result.code, signal: result.signal, stdout: handle.stdout(), stderr: handle.stderr() };
141	}
142	
143	/**
144	 * Starts the server (PORT=0 unless given) and waits for the listening line.
145	 * Returns { port, stop(), stdout(), stderr(), child }.
146	 */
147	export async function startServer({ cwd, env = {}, script }) {
148	  const handle = spawnServer({ cwd, env: { PORT: '0', ...env }, script });
149	  const stop = async () => {
150	    if (handle.child.exitCode === null && handle.child.signalCode === null) {
151	      handle.child.kill();
152	    }
153	    await handle.exited;
154	  };
155	  let timer;
156	  try {
157	    const port = await new Promise((resolve, reject) => {
158	      handle.child.stdout.on('data', () => {
159	        const match = LISTEN_RE.exec(handle.stdout());
160	        if (match) resolve(Number(match[1]));
161	      });
162	      handle.exited.then(({ code }) =>
163	        reject(new Error(`server exited (${code}) before listening: ${handle.stderr()}`)),
164	      );
165	      timer = setTimeout(() => reject(new Error('server did not print its listening line')), LISTEN_TIMEOUT_MS);
166	    });
167	    return { ...handle, port, stop };
168	  } catch (err) {
169	    await stop();
170	    throw err;
171	  } finally {
172	    clearTimeout(timer);
173	  }
174	}
175	
176	/**
177	 * One HTTP request with a raw path (sent as given, nothing normalised).
178	 * `chunks` (an array of strings/Buffers) sends the body in several writes instead of `body`.
179	 * Resolves to { status, headers, text, json } (json is undefined when the body is not JSON).
180	 */
181	export function request(port, { method = 'GET', path = '/', headers = {}, body, chunks } = {}) {
182	  return new Promise((resolve, reject) => {
183	    const req = httpRequest(
184	      { host: '127.0.0.1', port, method, path, headers, agent: false, timeout: REQUEST_TIMEOUT_MS },
185	      (res) => {
186	        const chunks = [];
187	        res.on('data', (c) => chunks.push(c));
188	        res.on('end', () => {
189	          const text = Buffer.concat(chunks).toString('utf8');
190	          let json;
191	          try {
192	            json = JSON.parse(text);
193	          } catch {
194	            json = undefined;
195	          }
196	          resolve({ status: res.statusCode, headers: res.headers, text, json });
197	        });
198	        res.on('error', reject);
199	      },
200	    );
201	    req.on('error', reject);
202	    req.on('timeout', () => req.destroy(new Error(`no reply to ${method} ${path}`)));
203	    for (const chunk of chunks ?? []) req.write(chunk);
204	    req.end(body);
205	  });
206	}
207	
208	/** POST /api/bookings with a JSON body (object, or a raw string/Buffer). */
209	export function postBooking(port, value, headers = JSON_HEADERS) {
210	  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
211	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
212	}
213	
214	export const getBookings = async (port, query = '') =>
215	  (await request(port, { path: `/api/bookings${query}` })).json.bookings;
216	
217	/**
218	 * Writes raw bytes to a socket and resolves to everything the server sent back
219	 * once it closes the connection (send `Connection: close`).
220	 */
221	export function rawRequest(port, data) {
222	  return new Promise((resolve, reject) => {
223	    const socket = connect(port, '127.0.0.1');
224	    socket.setTimeout(REQUEST_TIMEOUT_MS, () => socket.destroy(new Error('raw request got no full reply')));
225	    const chunks = [];
226	    socket.on('data', (c) => chunks.push(c));
227	    socket.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
228	    socket.on('error', reject);
229	    socket.write(data);
230	  });
231	}
232	
233	/** Opens a socket and returns it plus a getter for the bytes received so far. */
234	export function openSocket(port) {
235	  return new Promise((resolve, reject) => {
236	    const socket = connect(port, '127.0.0.1', () => resolve({ socket, received: () => text }));
237	    let text = '';
238	    socket.setEncoding('utf8');
239	    socket.on('data', (d) => (text += d));
240	    socket.on('error', reject);
241	  });
242	}
243	
244	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
245	export function isPortFree(port) {
246	  return new Promise((resolve) => {
247	    const probe = createNetServer();
248	    probe.once('error', () => resolve(false));
249	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
250	  });
251	}
252	
253	/** Binds a port (0 = any) on 127.0.0.1 and returns { port, close() }. */
254	export function occupyPort(port = 0) {
255	  return new Promise((resolve, reject) => {
256	    const blocker = createNetServer();
257	    blocker.once('error', reject);
258	    blocker.listen(port, '127.0.0.1', () =>
259	      resolve({
260	        port: blocker.address().port,
261	        close: () => new Promise((done) => blocker.close(() => done())),
262	      }),
263	    );
264	  });
265	}
266	
267	export const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
