1	// POST /api/bookings rules 1-3: content type, body size, JSON object, body read before reply.
2	import assert from 'node:assert/strict';
3	import { request as httpRequest } from 'node:http';
4	import { after, before, describe, test } from 'node:test';
5	import { rm } from 'node:fs/promises';
6	import {
7	  JSON_HEADERS,
8	  JSON_TYPE,
9	  booking,
10	  delay,
11	  makeTmpDir,
12	  openSocket,
13	  postBooking,
14	  rawRequest,
15	  request,
16	  startServer,
17	} from './helpers/server.mjs';
18	
19	const MSG_415 = 'content type must be application/json';
20	const MSG_413 = 'body too large';
21	const MSG_400 = 'body must be a JSON object';
22	const MSG_ROOM = 'room must be one of Aurora, Borealis, Cosmos';
23	const LIMIT = 10000;
24	
25	let tmp;
26	let srv;
27	let dayCounter = 0;
28	
29	before(async () => {
30	  tmp = await makeTmpDir();
31	  srv = await startServer({ cwd: tmp });
32	});
33	
34	after(async () => {
35	  await srv?.stop();
36	  if (tmp) await rm(tmp, { recursive: true, force: true });
37	});
38	
39	/** A valid booking on a never-used date so accepted cases never overlap. */
40	function freshBooking(overrides = {}) {
41	  dayCounter += 1;
42	  const month = String(1 + Math.floor(dayCounter / 28)).padStart(2, '0');
43	  const day = String(1 + (dayCounter % 28)).padStart(2, '0');
44	  return booking({ date: `2040-${month}-${day}`, ...overrides });
45	}
46	
47	function expectError(res, status, error) {
48	  assert.strictEqual(res.status, status);
49	  assert.deepStrictEqual(res.json, { error });
50	  assert.strictEqual(res.headers['content-type'], JSON_TYPE);
51	}
52	
53	function expect201(res) {
54	  assert.strictEqual(res.status, 201, res.text);
55	  assert.strictEqual(res.headers['content-type'], JSON_TYPE);
56	}
57	
58	/** Valid booking JSON padded with trailing spaces to exactly `bytes` bytes. */
59	function paddedBody(bytes) {
60	  const base = JSON.stringify(freshBooking());
61	  return base + ' '.repeat(bytes - Buffer.byteLength(base));
62	}
63	
64	/** Parses status line and JSON body out of a raw HTTP response. */
65	function parseRaw(text) {
66	  const status = Number(/^HTTP\/1\.1 (\d+)/.exec(text)?.[1]);
67	  const body = text.slice(text.indexOf('\r\n\r\n') + 4);
68	  return { status, body: JSON.parse(body) };
69	}
70	
71	describe('rule 1: content type 415', () => {
72	  const bad = [
73	    'text/plain',
74	    'application/jsonx',
75	    'application/json-patch+json',
76	    'text/json',
77	    'application/x-json',
78	    'application/ json',
79	    'application /json',
80	    'application',
81	    '',
82	    '"application/json"',
83	    'application/json,',
84	  ];
85	  test('no Content-Type header', async () => {
86	    expectError(await postBooking(srv.port, booking(), {}), 415, MSG_415);
87	  });
88	  for (const type of bad) {
89	    test(`type ${JSON.stringify(type)}`, async () => {
90	      const res = await postBooking(srv.port, booking(), { 'Content-Type': type });
91	      expectError(res, 415, MSG_415);
92	    });
93	  }
94	  test('application/json followed by NBSP byte', async () => {
95	    const body = Buffer.from(JSON.stringify(booking()));
96	    const head = Buffer.from(
97	      'POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json',
98	      'latin1',
99	    );
100	    const tail = Buffer.from(
101	      `\r\nContent-Length: ${body.length}\r\nConnection: close\r\n\r\n`,
102	      'latin1',
103	    );
104	    const text = await rawRequest(srv.port, Buffer.concat([head, Buffer.from([0xa0]), tail, body]));
105	    const parsed = parseRaw(text);
106	    assert.strictEqual(parsed.status, 415);
107	    assert.deepStrictEqual(parsed.body, { error: MSG_415 });
108	  });
109	});
110	
111	describe('rule 1: accepted content types', () => {
112	  const good = [
113	    'application/json',
114	    'APPLICATION/JSON',
115	    'Application/Json',
116	    'application/json; charset=utf-8',
117	    'Application/JSON ; charset=x',
118	    'application/json;',
119	    ' application/json',
120	    'application/json ',
121	    '\tapplication/json\t',
122	    ' \t application/json \t ;x',
123	    'application/json;charset=utf-8;foo=bar',
124	  ];
125	  for (const type of good) {
126	    test(`type ${JSON.stringify(type)}`, async () => {
127	      expect201(await postBooking(srv.port, freshBooking(), { 'Content-Type': type }));
128	    });
129	  }
130	});
131	
132	describe('rule order 1 > 2 > 3', () => {
133	  test('wrong type + 20000-byte body -> 415', async () => {
134	    const res = await postBooking(srv.port, 'x'.repeat(20000), { 'Content-Type': 'text/plain' });
135	    expectError(res, 415, MSG_415);
136	  });
137	  test('wrong type + invalid JSON -> 415', async () => {
138	    const res = await postBooking(srv.port, '{oops', { 'Content-Type': 'text/plain' });
139	    expectError(res, 415, MSG_415);
140	  });
141	  test('10001 bytes of x with JSON type -> 413', async () => {
142	    expectError(await postBooking(srv.port, 'x'.repeat(LIMIT + 1)), 413, MSG_413);
143	  });
144	});
145	
146	describe('rule 2: size limit', () => {
147	  test('exactly 10000 bytes -> 201', async () => {
148	    expect201(await postBooking(srv.port, paddedBody(LIMIT)));
149	  });
150	  test('10001 bytes -> 413', async () => {
151	    expectError(await postBooking(srv.port, paddedBody(LIMIT + 1)), 413, MSG_413);
152	  });
153	
154	  /** Booking JSON with an ignored "pad" key of 'é' sized to the target byte count. */
155	  function multiByteBody(bytes) {
156	    const base = JSON.stringify({ ...freshBooking(), pad: '' });
157	    const count = Math.floor((bytes - Buffer.byteLength(base)) / 2);
158	    let text = JSON.stringify({ ...JSON.parse(base), pad: 'é'.repeat(count) });
159	    text += ' '.repeat(bytes - Buffer.byteLength(text));
160	    return text;
161	  }
162	  test('multi-byte body of 10001 bytes (string shorter than 10000) -> 413', async () => {
163	    const text = multiByteBody(LIMIT + 1);
164	    assert.strictEqual(Buffer.byteLength(text), LIMIT + 1);
165	    assert.ok(text.length < LIMIT);
166	    expectError(await postBooking(srv.port, text), 413, MSG_413);
167	  });
168	  test('multi-byte body of exactly 10000 bytes -> 201', async () => {
169	    const text = multiByteBody(LIMIT);
170	    assert.strictEqual(Buffer.byteLength(text), LIMIT);
171	    assert.ok(text.length < LIMIT);
172	    expect201(await postBooking(srv.port, text));
173	  });
174	
175	  /** Chunked POST with no Content-Length, body split in 4 writes. */
176	  function chunkedPost(text) {
177	    return new Promise((resolve, reject) => {
178	      const req = httpRequest(
179	        {
180	          host: '127.0.0.1',
181	          port: srv.port,
182	          method: 'POST',
183	          path: '/api/bookings',
184	          agent: false,
185	          headers: { 'Content-Type': 'application/json', 'Transfer-Encoding': 'chunked' },
186	        },
187	        (res) => {
188	          const chunks = [];
189	          res.on('data', (c) => chunks.push(c));
190	          res.on('end', () => {
191	            const body = Buffer.concat(chunks).toString('utf8');
192	            resolve({ status: res.statusCode, json: JSON.parse(body), headers: res.headers, text: body });
193	          });
194	          res.on('error', reject);
195	        },
196	      );
197	      req.on('error', reject);
198	      const buf = Buffer.from(text);
199	      const third = Math.floor(buf.length / 3);
200	      req.write(buf.subarray(0, third));
201	      req.write(buf.subarray(third, 2 * third));
202	      req.write(buf.subarray(2 * third, buf.length - 1));
203	      req.end(buf.subarray(buf.length - 1));
204	    });
205	  }
206	  test('chunked totalling 10001 bytes -> 413', async () => {
207	    expectError(await chunkedPost(paddedBody(LIMIT + 1)), 413, MSG_413);
208	  });
209	  test('chunked totalling 10000 bytes -> 201', async () => {
210	    expect201(await chunkedPost(paddedBody(LIMIT)));
211	  });
212	});
213	
214	describe('huge bodies', () => {
215	  const huge = Buffer.alloc(5 * 1024 * 1024, 0x78);
216	  test('5 MB with JSON type -> 413', async () => {
217	    expectError(await postBooking(srv.port, huge), 413, MSG_413);
218	  });
219	  test('5 MB with text/plain -> 415', async () => {
220	    const res = await postBooking(srv.port, huge, { 'Content-Type': 'text/plain' });
221	    expectError(res, 415, MSG_415);
222	  });
223	  test('5 MB to PUT /api/bookings -> 405', async () => {
224	    const res = await request(srv.port, {
225	      method: 'PUT',
226	      path: '/api/bookings',
227	      headers: JSON_HEADERS,
228	      body: huge,
229	    });
230	    assert.strictEqual(res.status, 405);
231	  });
232	  test('5 MB to POST /nope -> 404', async () => {
233	    const res = await request(srv.port, {
234	      method: 'POST',
235	      path: '/nope',
236	      headers: JSON_HEADERS,
237	      body: huge,
238	    });
239	    assert.strictEqual(res.status, 404);
240	  });
241	});
242	
243	describe('body fully read before reply', () => {
244	  const cases = [
245	    { name: '415', path: '/api/bookings', type: 'text/plain', length: 100, first: 50, status: '415 Unsupported Media Type' },
246	    { name: '413', path: '/api/bookings', type: 'application/json', length: 20000, first: 10500, status: '413 Payload Too Large' },
247	    { name: '404', path: '/nope', type: 'text/plain', length: 100, first: 50, status: '404 Not Found' },
248	  ];
249	  for (const c of cases) {
250	    test(`${c.name}: no reply until the whole body arrived`, async () => {
251	      const { socket, received } = await openSocket(srv.port);
252	      const ended = new Promise((resolve) => socket.on('end', resolve));
253	      socket.write(
254	        `POST ${c.path} HTTP/1.1\r\nHost: x\r\nContent-Type: ${c.type}\r\n` +
255	          `Content-Length: ${c.length}\r\nConnection: close\r\n\r\n` +
256	          'x'.repeat(c.first),
257	      );
258	      await delay(300);
259	      assert.strictEqual(received(), '');
260	      socket.write('x'.repeat(c.length - c.first));
261	      await ended;
262	      const firstLine = received().split('\r\n')[0];
263	      assert.strictEqual(firstLine, `HTTP/1.1 ${c.status}`);
264	    });
265	  }
266	});
267	
268	describe('rule 3: JSON object', () => {
269	  const valid = () => JSON.stringify(freshBooking());
270	  const bad = [
271	    ['empty', () => ''],
272	    ['space', () => ' '],
273	    ['null', () => 'null'],
274	    ['array', () => '[]'],
275	    ['array of object', () => '[{}]'],
276	    ['string', () => '"x"'],
277	    ['number', () => '1'],
278	    ['true', () => 'true'],
279	    ['false', () => 'false'],
280	    ['open brace', () => '{'],
281	    ['trailing comma', () => '{"room":"Aurora",}'],
282	    ['single quotes', () => "{'room':'Aurora'}"],
283	    ['NaN', () => 'NaN'],
284	    ['BOM + valid JSON', () => Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(valid())])],
285	    ['0xFF + valid JSON', () => Buffer.concat([Buffer.from([0xff]), Buffer.from(valid())])],
286	    ['UTF-16LE JSON', () => Buffer.from(valid(), 'utf16le')],
287	  ];
288	  for (const [name, make] of bad) {
289	    test(`${name} -> 400`, async () => {
290	      expectError(await postBooking(srv.port, make()), 400, MSG_400);
291	    });
292	  }
293	  test('{} is an object -> room message', async () => {
294	    expectError(await postBooking(srv.port, '{}'), 400, MSG_ROOM);
