function chunkedPost(text) {
  return new Promise((resolve, reject) => {
    const req = httpRequest(
      {
        host: '127.0.0.1',
        port: srv.port,
        method: 'POST',
        path: '/api/bookings',
        agent: false,
        headers: { 'Content-Type': 'application/json', 'Transfer-Encoding': 'chunked' },
      },
      (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const body = Buffer.concat(chunks).toString('utf8');
          resolve({ status: res.statusCode, json: JSON.parse(body), headers: res.headers, text: body });
        });
        res.on('error', reject);
      },
    );
    req.on('error', reject);
    const buf = Buffer.from(text);
    const third = Math.floor(buf.length / 3);
    req.write(buf.subarray(0, third));
    req.write(buf.subarray(third, 2 * third));
    req.write(buf.subarray(2 * third, buf.length - 1));
    req.end(buf.subarray(buf.length - 1));
  });
}

